export class NumberPalette {
    _count = 0;
    //map id to value
    _palette = [];
    //map value to id
    _map = {};
    get size() {
        return this._count;
    }
    constructor(inital) {
        if (inital) {
            let length = inital.length;
            for (let i = 0; i < length; i++) {
                this.register(inital[i]);
            }
        }
    }
    register(value) {
        if (this._map[value] !== undefined)
            return this._map[value];
        const id = this._count;
        this._palette[id] = value;
        this._map[value] = id;
        this._count++;
        return id;
    }
    get() {
        return this._palette;
    }
    getMap() {
        return this._map;
    }
    isRegistered(id) {
        return this._map[id] !== undefined;
    }
    getId(value) {
        return this._map[value];
    }
    getValue(id) {
        return this._palette[id];
    }
}
